-- Trading calendar of stock_dataload (created automatically by the app / `python -m stock_dataload init-db`;
-- kept here for reference, generated from stock_dataload/trading_calendar.py).
--
-- Market          the markets a calendar is kept for and the rule set used to generate their days
--                 (us = weekends + NYSE/NASDAQ holidays, weekends = weekends only); NASDAQ, NYSE, AMEX are seeded
-- No_Trading_Day  one row per market and day the market is closed: weekends, holidays, ad-hoc closures
--                 (Source: generated by the yearly update | config = [quality] extra_holidays | manual)
-- Fill a year before it begins: python -m stock_dataload no-trading-days update --year YYYY

CREATE TABLE IF NOT EXISTS "Market" (
    "MarketId"  INTEGER PRIMARY KEY AUTOINCREMENT,
    "Market"    TEXT NOT NULL UNIQUE COLLATE NOCASE,   -- NASDAQ, NYSE, ...
    "Name"      TEXT,
    "Rules"     TEXT NOT NULL,                         -- us | weekends
    "Active"    INTEGER NOT NULL DEFAULT 1,
    "CreatedAt" TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS "No_Trading_Day" (
    "NoTradingDayId" INTEGER PRIMARY KEY AUTOINCREMENT,
    "Market"    TEXT NOT NULL COLLATE NOCASE,
    "TradeDate" TEXT NOT NULL,                         -- YYYY-MM-DD
    "Reason"    TEXT NOT NULL,                         -- weekend (Saturday) | Good Friday | ...
    "Source"    TEXT NOT NULL,                         -- generated | config | manual
    "CreatedAt" TEXT NOT NULL,
    CONSTRAINT "UQ_No_Trading_Day_Market_TradeDate" UNIQUE ("Market", "TradeDate"),
    CONSTRAINT "CK_No_Trading_Day_TradeDate" CHECK ("TradeDate" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]')
);
CREATE INDEX IF NOT EXISTS "IX_No_Trading_Day_TradeDate" ON "No_Trading_Day" ("TradeDate");
